import React, { useEffect, useRef, useState, useMemo } from 'react';
import Globe, { GlobeMethods } from 'react-globe.gl'; // Import GlobeMethods for ref typing
import * as satellite from 'satellite.js';
import * as THREE from 'three';

// Constants
const EARTH_RADIUS_KM = 6371; // km
const SAT_SIZE = 40; // km (made smaller for label clarity)
const TIME_STEP = 3000; // ms per frame
const ORBIT_PROPAGATION_DURATION_MINUTES = 30; 
const ORBIT_PROPAGATION_STEP_MINUTES = 1; // Step size for orbit calculation
const LABEL_FONT_SIZE = 12; // Adjusted font size for labels
const LABEL_COLOR = 'rgba(255, 255, 255, 0.95)'; // White label text
const LABEL_BG_COLOR = 'rgba(0, 0, 0, 0.5)'; // Semi-transparent black background for label

// Helper Function to convert radians to degrees
const radiansToDegrees = (radians: number): number => (radians * 180) / Math.PI;

// --- Satellite Data Structure ---
interface SatelliteDefinition {
  name: string;
  tle1: string;
  tle2: string;
  color: string; // Color for the satellite object and its orbit
}

// --- TLE Data with Colors ---
// Using the TLEs provided by the user
